@GetMapping(value = "/search") @ResponseStatus(HttpStatus.OK) public String search(@RequestParam String name) { try (Connection connection = DriverManager.getConnection("jdbc:sqlite:sqlitestorage.db")) { PreparedStatement statement = connection.prepareStatement("SELECT * FROM users WHERE name = ?"); statement.setString(1, name); ResultSet resultSet = statement.executeQuery(); if (resultSet.next()) { return "User found: " + resultSet.getString("name"); } return "No user found"; } catch (Exception ex) { return "Query failed: " + ex.getMessage(); } }